"""Small YAML config helper (dot-access + deep merge + CLI overrides)."""

from __future__ import annotations

import copy
import os
from typing import Any, Dict, Iterable, Mapping, Optional

import yaml


class Config(dict):
    """``dict`` with attribute access and nested wrapping."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        for key, value in list(self.items()):
            self[key] = self._wrap(value)

    # ------------------------------------------------------------------ #
    @staticmethod
    def _wrap(value: Any) -> Any:
        if isinstance(value, Config):
            return value
        if isinstance(value, Mapping):
            return Config(value)
        if isinstance(value, (list, tuple)):
            return type(value)(Config._wrap(v) for v in value)
        return value

    def __setitem__(self, key: Any, value: Any) -> None:
        super().__setitem__(key, self._wrap(value))

    def __getattr__(self, item: str) -> Any:
        try:
            return self[item]
        except KeyError as exc:  # pragma: no cover - trivial
            raise AttributeError(item) from exc

    def __setattr__(self, key: str, value: Any) -> None:
        self[key] = value

    # ------------------------------------------------------------------ #
    def get_path(self, dotted: str, default: Any = None) -> Any:
        node: Any = self
        for part in dotted.split("."):
            if not isinstance(node, Mapping) or part not in node:
                return default
            node = node[part]
        return node

    def set_path(self, dotted: str, value: Any) -> None:
        parts = dotted.split(".")
        node: Any = self
        for part in parts[:-1]:
            if part not in node or not isinstance(node[part], Mapping):
                node[part] = Config()
            node = node[part]
        node[parts[-1]] = value

    def to_dict(self) -> Dict[str, Any]:
        def unwrap(value: Any) -> Any:
            if isinstance(value, Mapping):
                return {k: unwrap(v) for k, v in value.items()}
            if isinstance(value, (list, tuple)):
                return [unwrap(v) for v in value]
            return value

        return unwrap(dict(self))


def merge_configs(base: Mapping[str, Any], override: Mapping[str, Any]) -> Config:
    """Recursively merge ``override`` into a copy of ``base``."""
    out: Dict[str, Any] = copy.deepcopy(dict(base))
    for key, value in override.items():
        if isinstance(value, Mapping) and isinstance(out.get(key), Mapping):
            out[key] = merge_configs(out[key], value)
        else:
            out[key] = copy.deepcopy(value)
    return Config(out)


def load_config(path: str, overrides: Optional[Iterable[str]] = None) -> Config:
    """Load a YAML file and apply ``key.sub=value`` style overrides."""
    with open(path, "r") as handle:
        cfg = Config(yaml.safe_load(handle) or {})

    # A config may declare a `defaults` list whose entries are merged first so
    # that task configs stay short (mirrors the DexPBT/IsaacGym layout).
    defaults = cfg.pop("defaults", None)
    if defaults:
        base = Config()
        for name in defaults:
            base = merge_configs(base, Config(yaml.safe_load(open(_resolve(path, name)))))
        cfg = merge_configs(base, cfg)

    for item in overrides or []:
        if "=" not in item:
            raise ValueError(f"Override '{item}' is not of the form key=value")
        key, raw = item.split("=", 1)
        cfg.set_path(key.strip(), yaml.safe_load(raw))

    cfg.setdefault("config_path", os.path.abspath(path))
    return cfg


def _resolve(config_path: str, name: str) -> str:
    candidate = os.path.join(os.path.dirname(os.path.abspath(config_path)), name)
    if os.path.exists(candidate):
        return candidate
    if os.path.exists(name):
        return name
    raise FileNotFoundError(f"Could not resolve default config '{name}'")

"""Running mean/std, used for observation normalisation."""

from __future__ import annotations

import numpy as np
import torch


class RunningMeanStd:
    """Welford / parallel-variance running statistics."""

    def __init__(self, shape=(), epsilon: float = 1e-4) -> None:
        self.mean = np.zeros(shape, dtype=np.float64)
        self.var = np.ones(shape, dtype=np.float64)
        self.count = epsilon

    def update(self, x: np.ndarray) -> None:
        x = np.asarray(x, dtype=np.float64)
        if x.ndim == self.mean.ndim:
            x = x[None]
        batch_mean = np.mean(x, axis=0)
        batch_var = np.var(x, axis=0)
        batch_count = x.shape[0]

        delta = batch_mean - self.mean
        total = self.count + batch_count
        new_mean = self.mean + delta * batch_count / total
        m_a = self.var * self.count
        m_b = batch_var * batch_count
        m2 = m_a + m_b + np.square(delta) * self.count * batch_count / total
        self.mean = new_mean
        self.var = m2 / total
        self.count = total

    @property
    def std(self) -> np.ndarray:
        return np.sqrt(self.var)

    def state_dict(self):
        return {"mean": self.mean, "var": self.var, "count": self.count}

    def load_state_dict(self, state) -> None:
        self.mean = np.asarray(state["mean"], dtype=np.float64)
        self.var = np.asarray(state["var"], dtype=np.float64)
        self.count = float(state["count"])


class Normalizer:
    """Normalise a tensor with (frozen) running statistics."""

    def __init__(self, shape, device: str = "cpu", clip: float = 5.0) -> None:
        self.stats = RunningMeanStd(shape)
        self.device = device
        self.clip = clip

    def update(self, x) -> None:
        if isinstance(x, torch.Tensor):
            x = x.detach().cpu().numpy()
        self.stats.update(x)

    def normalize(self, x: torch.Tensor) -> torch.Tensor:
        mean = torch.as_tensor(self.stats.mean, dtype=x.dtype, device=x.device)
        std = torch.as_tensor(self.stats.std, dtype=x.dtype, device=x.device)
        out = (x - mean) / (std + 1e-8)
        if self.clip is not None:
            out = torch.clamp(out, -self.clip, self.clip)
        return out

