"""Plotting / aggregation helpers for the paper's figures and tables.

The paper reports "the mean and standard error in the plots.  In each plot, the
solid line is y(t) = 1/n sum_i y_i(t) while the width of the shaded region is
determined by standard error" (Sec. 5.2), so every helper here returns the mean
and the standard error over seeds; curves are plotted with a shaded region of
+/- 2 standard errors.
"""

from __future__ import annotations

import csv
import os
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np


def load_progress(csv_path: str) -> Dict[str, np.ndarray]:
    with open(csv_path, "r") as handle:
        rows = list(csv.DictReader(handle))
    columns: Dict[str, List[float]] = {}
    for row in rows:
        for key, value in row.items():
            if key is None:
                continue
            try:
                columns.setdefault(key, []).append(float(value))
            except (TypeError, ValueError):
                continue
    return {key: np.asarray(values) for key, values in columns.items()}


def standard_error(values: np.ndarray, axis: int = 0) -> np.ndarray:
    n = values.shape[axis]
    if n <= 1:
        return np.zeros_like(values.mean(axis=axis))
    return values.std(axis=axis, ddof=1) / np.sqrt(n)


def _resample(x: np.ndarray, y: np.ndarray, grid: np.ndarray) -> np.ndarray:
    """Interpolate (and forward-fill) a seed's curve onto a common x grid."""
    if len(x) == 0:
        return np.full_like(grid, np.nan, dtype=np.float64)
    order = np.argsort(x)
    x, y = x[order], y[order]
    out = np.interp(grid, x, y, left=y[0], right=y[-1])
    return out


def curve_stats(
    run_dirs: Sequence[str],
    metric: str,
    x_metric: str = "env_steps",
    num_points: int = 200,
    reduce: str = "mean",
    csv_name: str = "progress.csv",
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Mean and standard error of ``metric`` across seeds."""
    curves = []
    grid: Optional[np.ndarray] = None
    for run_dir in run_dirs:
        path = os.path.join(run_dir, csv_name)
        if not os.path.exists(path):
            continue
        data = load_progress(path)
        if metric not in data or x_metric not in data:
            continue
        y = _reduce_policies(data, metric, reduce)
        x = data[x_metric]
        if grid is None:
            grid = np.linspace(x.min(), x.max(), num_points)
        curves.append(_resample(x, y, grid))
    if not curves or grid is None:
        return np.asarray([]), np.asarray([]), np.asarray([])
    stacked = np.vstack(curves)
    return grid, stacked.mean(axis=0), 2.0 * standard_error(stacked, axis=0)


def _reduce_policies(data: Dict[str, np.ndarray], metric: str, reduce: str) -> np.ndarray:
    """Handle multi-policy metrics such as ``eval3/successes``.

    DexPBT evaluates its whole population; the reported number for a
    population-based method is the performance of the *best* member (that is
    what population-based training selects), while SAPG reports its leader.
    """
    if metric in data:
        return data[metric]
    suffixes = [key for key in data if key.endswith("/" + metric.split("/")[-1]) and key != metric]
    if not suffixes:
        raise KeyError(f"Metric '{metric}' not found in progress.csv")
    stacked = np.vstack([data[key] for key in suffixes])
    if reduce == "max":
        return np.nanmax(stacked, axis=0)
    if reduce == "min":
        return np.nanmin(stacked, axis=0)
    return np.nanmean(stacked, axis=0)


def smooth(values: np.ndarray, window: int) -> np.ndarray:
    if window <= 1 or values.size == 0:
        return values
    kernel = np.ones(window) / float(window)
    return np.convolve(values, kernel, mode="same")


def plot_curves(
    series: Dict[str, Sequence[str]],
    out_path: str,
    metric: str = "eval0/successes",
    x_metric: str = "env_steps",
    xlabel: str = "environment steps",
    ylabel: Optional[str] = None,
    title: Optional[str] = None,
    smooth_window: int = 1,
    logx: bool = False,
    reduce: str = "mean",
    ylim: Optional[Tuple[float, float]] = None,
) -> str:
    """Plot one curve per method (mean over seeds with a +/-2 SE band)."""
    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    fig, ax = plt.subplots(figsize=(6, 4.5))
    for label, run_dirs in series.items():
        x, mean, band = curve_stats(run_dirs, metric, x_metric=x_metric, reduce=reduce)
        if x.size == 0:
            continue
        ax.plot(x, smooth(mean, smooth_window), label=label)
        ax.fill_between(x, smooth(mean - band, smooth_window), smooth(mean + band, smooth_window), alpha=0.2)
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel or metric)
    if title:
        ax.set_title(title)
    if logx:
        ax.set_xscale("log")
    if ylim is not None:
        ax.set_ylim(*ylim)
    ax.grid(alpha=0.3)
    ax.legend(fontsize=8)
    fig.tight_layout()
    os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
    fig.savefig(out_path, dpi=200)
    plt.close(fig)
    return out_path


def summarise_final(
    series: Dict[str, Sequence[str]],
    metric: str,
    x_metric: str = "env_steps",
    last_fraction: float = 0.1,
    reduce: str = "mean",
) -> Dict[str, Dict[str, float]]:
    """Mean +/- standard error of the final (asymptotic) performance."""
    summary: Dict[str, Dict[str, float]] = {}
    for label, run_dirs in series.items():
        finals: List[float] = []
        for run_dir in run_dirs:
            path = os.path.join(run_dir, "progress.csv")
            if not os.path.exists(path):
                continue
            data = load_progress(path)
            if metric not in data and not any(k.endswith("/" + metric.split("/")[-1]) for k in data):
                continue
            values = _reduce_policies(data, metric, reduce)
            steps = data.get(x_metric, np.arange(values.size))
            keep = steps >= steps.max() * (1.0 - last_fraction)
            values = values[keep]
            if values.size:
                finals.append(float(np.mean(values)))
        if finals:
            summary[label] = {
                "mean": float(np.mean(finals)),
                "stderr": float(np.std(finals, ddof=1) / np.sqrt(len(finals))) if len(finals) > 1 else 0.0,
                "n_seeds": float(len(finals)),
            }
    return summary


def summary_to_markdown(summary: Dict[str, Dict[str, float]], float_format: str = "{:.3g}") -> str:
    lines = ["| method | mean | std. error | seeds |", "| --- | --- | --- | --- |"]
    for label, stats in summary.items():
        lines.append(
            f"| {label} | {float_format.format(stats['mean'])} | "
            f"{float_format.format(stats['stderr'])} | {int(stats['n_seeds'])} |"
        )
    return "\n".join(lines)


def summary_to_latex(summary: Dict[str, Dict[str, float]], float_format: str = "{:.3g}") -> str:
    lines = [r"\begin{tabular}{|c|c|c|}", r"\hline method & mean & std. error \\", r"\hline"]
    for label, stats in summary.items():
        lines.append(
            f"{label} & {float_format.format(stats['mean'])} & {float_format.format(stats['stderr'])} \\\\"
        )
    lines += [r"\hline", r"\end{tabular}"]
    return "\n".join(lines)

"""Discovery helpers for run directories.

Convention: every run lives in ``<root>/<label>_<task>_seed<seed>`` where
``task`` is one of the five benchmark tasks (or the toy task) and ``label`` is
the method / ablation name, e.g. ``sapg_entropy0.005_reorientation_seed3``.
"""

from __future__ import annotations

import os
import re
from typing import Dict, Iterable, List, Sequence, Tuple

from ..envs import BENCHMARK_TASKS, TOY_TASKS

KNOWN_TASKS = tuple(BENCHMARK_TASKS) + tuple(TOY_TASKS)
SEED_PATTERN = re.compile(r"_seed(\d+)$")


def parse_run_dir(name: str, tasks: Sequence[str] = KNOWN_TASKS) -> Tuple[str, str, int]:
    seed_match = SEED_PATTERN.search(name)
    seed = int(seed_match.group(1)) if seed_match else 0
    stem = name[: seed_match.start()] if seed_match else name
    for task in sorted(tasks, key=len, reverse=True):
        if stem.endswith("_" + task):
            return stem[: -(len(task) + 1)], task, seed
    raise ValueError(f"Could not parse run directory '{name}' (expected '<label>_<task>_seed<k>')")


def collect_runs(
    root: str,
    tasks: Sequence[str] = KNOWN_TASKS,
    labels: Iterable[str] = (),
    seeds: Iterable[int] = (),
) -> Dict[str, Dict[str, List[str]]]:
    """Return ``{task: {label: [run_dir, ...]}}``."""
    labels = set(labels)
    seeds = set(seeds)
    runs: Dict[str, Dict[str, List[str]]] = {}
    if not os.path.isdir(root):
        return runs
    for name in sorted(os.listdir(root)):
        path = os.path.join(root, name)
        if not os.path.isdir(path):
            continue
        try:
            label, task, seed = parse_run_dir(name, tasks)
        except ValueError:
            continue
        if labels and label not in labels:
            continue
        if seeds and seed not in seeds:
            continue
        runs.setdefault(task, {}).setdefault(label, []).append(path)
    for task in runs:
        for label in runs[task]:
            runs[task][label] = sorted(runs[task][label])
    return runs


def default_metric(task: str) -> str:
    """Successes for the hard AllegroKuka tasks, episode reward otherwise."""
    if task in ("regrasping", "throw", "reorientation"):
        return "eval0/successes"
    return "eval0/episode_reward"

#!/usr/bin/env python3
"""Enumerate (and optionally launch) the full experiment matrix of the paper.

The paper reports 5 manipulation tasks x {SAPG, PPO, DexPBT, PQL} x 5 seeds plus
the Sec. 6.3 ablations, each run collecting ~2e10 transitions (48-60 h on a
single GPU).  Such runs are executed *outside* this environment; this script
writes the exact commands so that they can be launched on a cluster.

Example::

    python scripts/run_experiments.py --dry-run --out experiments/commands.sh
    python scripts/run_experiments.py --execute --workers 2
"""

from __future__ import annotations

import argparse
import os
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

CONFIGS = {
    "regrasping": {
        "sapg": "sapg/configs/sapg_allegrokuka_regrasping.yaml",
        "ppo": "sapg/configs/ppo_allegrokuka.yaml",
        "pbt": "sapg/configs/pbt_allegrokuka.yaml",
        "pql": "sapg/configs/pql_allegrokuka.yaml",
    },
    "throw": {
        "sapg": "sapg/configs/sapg_allegrokuka_throw.yaml",
        "ppo": "sapg/configs/ppo_allegrokuka.yaml",
        "pbt": "sapg/configs/pbt_allegrokuka.yaml",
        "pql": "sapg/configs/pql_allegrokuka.yaml",
    },
    "reorientation": {
        "sapg": "sapg/configs/sapg_allegrokuka_reorientation.yaml",
        "ppo": "sapg/configs/ppo_allegrokuka.yaml",
        "pbt": "sapg/configs/pbt_allegrokuka.yaml",
        "pql": "sapg/configs/pql_allegrokuka.yaml",
    },
    "shadow_hand": {
        "sapg": "sapg/configs/sapg_shadow_hand.yaml",
        "ppo": "sapg/configs/ppo_inhand.yaml",
        "pbt": "sapg/configs/pbt_inhand.yaml",
        "pql": "sapg/configs/pql_inhand.yaml",
    },
    "allegro_hand": {
        "sapg": "sapg/configs/sapg_allegro_hand.yaml",
        "ppo": "sapg/configs/ppo_inhand.yaml",
        "pbt": "sapg/configs/pbt_inhand.yaml",
        "pql": "sapg/configs/pql_inhand.yaml",
    },
}

ABLATIONS = {
    "sapg_no_offpolicy": "sapg/configs/ablations/sapg_no_offpolicy.yaml",
    "sapg_symmetric": "sapg/configs/ablations/sapg_symmetric.yaml",
    "sapg_high_offpolicy": "sapg/configs/ablations/sapg_high_offpolicy_ratio.yaml",
    "sapg_entropy0.003": "sapg/configs/ablations/sapg_entropy_0003.yaml",
    "sapg_entropy0.005": "sapg/configs/ablations/sapg_entropy_0005.yaml",
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run the paper's experiment matrix")
    parser.add_argument("--tasks", nargs="*", default=list(CONFIGS))
    parser.add_argument("--methods", nargs="*", default=["sapg", "ppo", "pbt", "pql"])
    parser.add_argument("--seeds", type=int, nargs="*", default=[0, 1, 2, 3, 4])
    parser.add_argument("--with-ablations", action="store_true")
    parser.add_argument("--logroot", default="runs")
    parser.add_argument("--out", default="experiments/commands.sh")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--workers", type=int, default=1)
    return parser.parse_args()


def build_commands(args) -> list:
    commands = []
    for task in args.tasks:
        for method in args.methods:
            if method not in CONFIGS[task]:
                continue
            for seed in args.seeds:
                logdir = os.path.join(args.logroot, f"{method}_{task}_seed{seed}")
                commands.append(
                    "python scripts/train.py --config {cfg} --logdir {logdir} --seed {seed}".format(
                        cfg=CONFIGS[task][method], logdir=logdir, seed=seed
                    )
                )
        if args.with_ablations:
            for label, cfg in ABLATIONS.items():
                for seed in args.seeds:
                    logdir = os.path.join(args.logroot, f"{label}_{task}_seed{seed}")
                    commands.append(
                        "python scripts/train.py --config {cfg} --logdir {logdir} "
                        "--seed {seed} --set env.name={task}".format(
                            cfg=cfg, logdir=logdir, seed=seed, task=task
                        )
                    )
    return commands


def main() -> None:
    args = parse_args()
    commands = build_commands(args)
    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    with open(args.out, "w") as handle:
        handle.write("#!/usr/bin/env bash\nset -euo pipefail\n\n")
        handle.write("\n".join(commands) + "\n")
    os.chmod(args.out, 0o755)
    print(f"[run_experiments] {len(commands)} runs written to {args.out}")

    if args.execute:
        from concurrent.futures import ThreadPoolExecutor

        def run(command: str) -> int:
            return subprocess.call(command, shell=True)

        with ThreadPoolExecutor(max_workers=args.workers) as pool:
            list(pool.map(run, commands))


if __name__ == "__main__":
    main()

